def compute(vars):
    value_2019 = vars["v1"]
    value_2018 = vars["v2"]
    threshold = 50000

    below_threshold = {
        2019: value_2019 < threshold,
        2018: value_2018 < threshold,
    }
    years = [year for year, is_below in below_threshold.items() if is_below]

    return {
        "value": years[0] if years else None,
        "trace": {
            "threshold": threshold,
            "below_threshold": below_threshold,
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
